\begin{figure}[t]
\centering
\usetikzlibrary{arrows.meta, positioning, shapes.multipart}
\tikzset{
  block/.style={
    rectangle split, rectangle split parts=2,
    rectangle split part fill={black!10,white},
    draw=black!70, rounded corners=2pt,
    text width=42mm, align=center,
    font=\footnotesize
  },
  arrow/.style={-Latex, thick}
}
\scalebox{0.9}{
\begin{tikzpicture}[node distance=15mm and 20mm]


  \node[block] (mse)
    {Proposition~\ref{Pr:MSE(1)}
     \nodepart{second}  Derivation of the exact MSE as a function of $(d_1,d_2)$};

  \node[block, right=of mse] (kkt)
    {KKT Conditions
     \nodepart{second} Reformulation as a nonlinear system~\eqref{eq:optimal_nonlinear}};

  \node[block, right=of kkt] (stationary)
    {From \eqref{eq:optimal_nonlinear}
     \nodepart{second} Identifying all possible solutions};

  \node[block, below=of stationary] (hessian)
    {Lemmas~\ref{lem:Boundries} and  \ref{lem:Boundries2}
     \nodepart{second} Bordered Hessian test to \\ identify the saddle points and SNR threshold~$\xi_1$};





  \node[block, left=of hessian] (encoder)
    {Proposition~\ref{Pr:Optmizaiton}
     \nodepart{second} 
  Ensuring the uniqueness of the central intersection};


  \draw[-latex] (mse) -- (kkt);
  \draw[-latex] (kkt) -- (stationary);
  \draw[-latex] (stationary) -- (hessian);
  \draw[-latex] (hessian) -- (encoder);


\end{tikzpicture}
}
\caption{Proof outline for Theorem~\ref{th:Optmizaiton}. 
Proposition~\ref{Pr:MSE(1)} provides a closed-form MSE approximation in terms of the encoder parameters.  The KKT conditions lead to the nonlinear system~\eqref{eq:optimal_nonlinear}. 
Applying Lemmas~\ref{lem:Boundries} and~\ref{lem:Boundries2} with the bordered Hessian identifies the saddle points and establishes the SNR threshold~$\xi_1$. 
Finally, Proposition~\ref{Pr:Optmizaiton} proves the uniqueness of the global minimizer and the corresponding optimal encoder parameters~$(d_1^*,d_2^*)$}
\label{fig:proof_theorem1}
\end{figure}
